#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals trigo. Set Implicit Arguments. Unset Strict Implicit.Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Theorem triangle_side_x_value : forall (A B C : R * R) (x y : R), let AC := sqrt ((fst A - fst C)^2+(snd A - snd C)^2) in let BC := sqrt ((fst B - fst C)^2+(snd B - snd C)^2) in let AB := sqrt ((fst A - fst B)^2+(snd A - snd B)^2) in AC = 5 -> ((fst A - fst C)*(fst B - fst C)+(snd A - snd C)*(snd B - snd C)=0) -> cos_angle (A-C) (B-C) = 1/2 -> BC = x -> x = 5*sqrt 3. Proof. by []. Qed.
